tempTrainer.TrainAndEvaluate();

realBuilder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(tempTrainer.ModelPath);

var realApp = realBuilder.Build();
realApp.MapControllers();
realApp.Run();

