arguments.new_str:
using Microsoft.Extensions.ML;
using TicketClassifier.Models;
using TicketClassifier.Services;

var builder = WebApplication.CreateBuilder(args);
builder.Services.AddControllers();
builder.Services.AddSingleton<TicketModelTrainer>();

// Train model at startup so the model file exists for the pool
var env = builder.Environment;
var loggerFactory = LoggerFactory.Create(b => b.AddConsole());
var trainer = new TicketModelTrainer(
    loggerFactory.CreateLogger<TicketModelTrainer>(), env);
trainer.TrainAndEvaluate();

builder.Services.AddPredictionEnginePool<TicketInput, TicketPrediction>()
    .FromFile(trainer.ModelPath);

var app = builder.Build();
app.MapControllers();
app.Run();

